#include <bits/stdc++.h>
#define endl '\n'
using namespace std;
using ll = long long;
using ull = unsigned long long;
const int N = 1005, B = 16;

int n, m, k, w, beg[N], row[N];
ull same[N][B], mask[B], group[B];
vector<int> off, val;
vector<ull> a, b, lim, f, g;
vector<pair<int, int>> d;

void build() {
    k = (n + 63) >> 6;
    w = 0;
    lim.clear();
    for (int i = 0; i < n - 1; i++) {
        beg[i] = (i + 1) >> 6;
        row[i] = w;
        for (int j = beg[i]; j < k; j++) {
            ull t = ~0ULL;
            if (j == beg[i]) t &= ~0ULL << ((i + 1) & 63);
            if (j == k - 1 && (n & 63)) t &= (1ULL << (n & 63)) - 1;
            lim.push_back(t);
            w++;
        }
    }
    a.assign((size_t)m * w, 0);
    b.resize((size_t)m * w);
    for (int j = 0; j < m; j++) {
        d.clear();
        for (int i = 0; i < n; i++) {
            int p = i * m + j;
            for (int t = off[p]; t < off[p + 1]; t++) d.emplace_back(val[t], i);
        }
        sort(d.begin(), d.end());
        memset(same, 0, sizeof(same));
        for (int l = 0, r; l < (int)d.size(); l = r) {
            r = l + 1;
            while (r < (int)d.size() && d[r].first == d[l].first) r++;
            if (r - l == 1) continue;
            fill(group, group + k, 0);
            for (int t = l; t < r; t++) {
                int p = d[t].second;
                group[p >> 6] |= 1ULL << (p & 63);
            }
            for (int t = l; t < r; t++) {
                int p = d[t].second;
                for (int h = 0; h < k; h++) same[p][h] |= group[h];
            }
        }
        ull *p = a.data() + (size_t)j * w;
        for (int i = 0; i < n - 1; i++)
            for (int h = beg[i]; h < k; h++) {
                int t = row[i] + h - beg[i];
                p[t] = ~same[i][h] & lim[t];
            }
    }
}

bool check(int l, int r) {
    if (l > r) {
        for (int i = 0; i < w; i++) if (g[i] != lim[i]) return false;
    } else {
        ull *p = a.data() + (size_t)l * w;
        ull *q = b.data() + (size_t)l * w;
        for (int i = 0; i < w; i++)
            if ((q[i] | g[i] | (p[i] & f[i])) != lim[i]) return false;
    }
    return true;
}

ll solve() {
    f.assign(w, 0);
    g.assign(w, 0);
    int l = 0, end = -1;
    ll ans = 0;
    for (int r = 0; r < m; r++) {
        ull *p = a.data() + (size_t)r * w;
        for (int i = 0; i < w; i++) {
            g[i] |= f[i] & p[i];
            f[i] |= p[i];
        }
        while (l <= r && check(l, end)) {
            if (l > end) {
                fill(f.begin(), f.end(), 0);
                fill(g.begin(), g.end(), 0);
                for (int j = r; j >= l; j--) {
                    ull *p = a.data() + (size_t)j * w;
                    ull *q = b.data() + (size_t)j * w;
                    for (int i = 0; i < w; i++) {
                        g[i] |= f[i] & p[i];
                        f[i] |= p[i];
                        p[i] = f[i];
                        q[i] = g[i];
                    }
                }
                end = r;
                fill(f.begin(), f.end(), 0);
                fill(g.begin(), g.end(), 0);
            }
            l++;
        }
        ans += l;
    }
    return ans;
}

int main() {
#ifndef LOCAL
    freopen("card.in", "r", stdin);
    freopen("card.out", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int _;
    cin >> _;
    while (_--) {
        cin >> n >> m;
        off.resize(n * m + 1);
        off[0] = 0;
        for (int i = 0, c; i < n * m; i++) {
            cin >> c;
            off[i + 1] = off[i] + c;
        }
        val.resize(off.back());
        for (int &x : val) cin >> x;
        if (n == 1) {
            cout << 1LL * m * (m + 1) / 2 << endl;
            continue;
        }
        build();
        cout << solve() << endl;
        vector<ull>().swap(a);
        vector<ull>().swap(b);
    }
    return 0;
}

